let calendarMode='month';
let calendarCursor=new Date(new Date().getFullYear(),new Date().getMonth(),1);
const weekLabels=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];
function localISO(value){const date=new Date(value);return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function currentCalendarDay(){return localISO(new Date())}
function sessionsForDay(value){return state.sessions.filter(session=>session.date===value).sort((a,b)=>a.begins-b.begins)}
function calendarMove(step){if(calendarMode==='month')calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+step,1);else calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth(),calendarCursor.getDate()+step*7);render()}
function calendarToday(){calendarCursor=new Date();render()}
function weekStart(value){const date=new Date(value.getFullYear(),value.getMonth(),value.getDate());date.setDate(date.getDate()-(date.getDay()+6)%7);return date}
function weekTitle(){const start=weekStart(calendarCursor),end=new Date(start);end.setDate(start.getDate()+6);return `${start.toLocaleDateString(locale(),{day:'numeric',month:'short'})} — ${end.toLocaleDateString(locale(),{day:'numeric',month:'short',year:'numeric'})}`}
function calendarHeader(){const title=calendarMode==='month'?calendarCursor.toLocaleDateString(locale(),{month:'long',year:'numeric'}):weekTitle();return html`<div class="calendar-toolbar"><div><span class="eyebrow">Расписание</span><h1>${e(title)}</h1></div><div class="calendar-actions"><div class="calendar-switch"><button class="${calendarMode==='month'?'active':''}" onclick="calendarMode='month';calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth(),1);render()">Месяц</button><button class="${calendarMode==='week'?'active':''}" onclick="calendarMode='week';calendarCursor=new Date();render()">Неделя</button></div><button onclick="calendarToday()">Сегодня</button></div></div><div class="calendar-pager"><button aria-label="Предыдущий период" onclick="calendarMove(-1)">←</button><button aria-label="Следующий период" onclick="calendarMove(1)">→</button></div>`}
function calendarView(){return html`<section class="calendar-page">${calendarHeader()}<div class="calendar-grid-wrap"><div class="calendar-weekdays">${weekLabels.map(label=>html`<span>${label}</span>`).join('')}</div><div class="calendar-grid ${calendarMode}">${calendarCells()}</div></div><p class="calendar-hint">Нажмите на день, чтобы увидеть тренировки.</p></section>`}
function calendarCells(){const first=calendarMode==='month'?new Date(calendarCursor.getFullYear(),calendarCursor.getMonth(),1):weekStart(calendarCursor);const start=new Date(first);if(calendarMode==='month')start.setDate(1-(first.getDay()+6)%7);const count=calendarMode==='month'?42:7;const today=currentCalendarDay();return Array.from({length:count},(_,index)=>{const date=new Date(start);date.setDate(start.getDate()+index);const value=localISO(date),sessions=sessionsForDay(value),outside=calendarMode==='month'&&date.getMonth()!==calendarCursor.getMonth();if(outside)return html`<span class="calendar-blank" aria-hidden="true"></span>`;return html`<button class="calendar-day ${value===today?'today':''} ${sessions.length?'has-sessions':''}" onclick="openCalendarDay('${value}')" aria-label="${e(value)}: ${sessions.length} тренировок"><span>${date.getDate()}</span></button>`}).join('')}
function openCalendarDay(value){const sessions=sessionsForDay(value);modal(html`<div class="calendar-day-dialog"><span class="eyebrow">${e(formatDate(value))}</span><h2>${sessions.length?'Тренировки дня':'Нет тренировок'}</h2>${sessions.map(session=>sessionDetailCard(session)).join('')||html`<p>На этот день занятий нет.</p>`}<div class="actions"><button class="primary" onclick="closeDialog()">Закрыть</button></div></div>`)}
function sessionDetailCard(session){const members=session.members.map(id=>state.students.find(person=>person.telegramId===id)).filter(Boolean),shown=members.slice(0,4),group=state.groups.find(item=>item.id===session.group);return html`<article class="calendar-session-detail ${sessionStatus(session)}"><div class="calendar-session-time"><strong>${e(session.time)}</strong><span>${session.durationMinutes||Math.round((session.ends-session.begins)/60)} min</span></div><div class="calendar-session-body"><div class="session-detail-top"><span class="badge">${e(group?.type||status(session))}</span><button class="text-action" onclick="openSession('${session.id}')">Open →</button></div><h3>${e(session.name)}</h3><p>📍 ${e(session.place)}</p><div class="calendar-members"><span>Participants · ${members.length}</span>${members.length?html`<div class="avatar-stack">${shown.map(person=>html`<button title="${e(person.displayName||person.fullName)}" onclick="navigateStudent(${person.telegramId})">${e((person.displayName||person.fullName).slice(0,1))}</button>`).join('')}${members.length>shown.length?html`<i>+${members.length-shown.length}</i>`:''}</div>`:html`<span class="meta">No students yet.</span>`}</div></div></article>`}
